(()=>{
const views={timeline:['Timeline','How do records and reported events unfold over time?','Explore dated documents and reported events in sequence, then inspect the sources behind an entry.','UFO Files Timeline view showing dated records and reported events across the archive'],network:['Relationships','Which people, places, and subjects appear together?','Explore relationships extracted from the archive, then inspect the source context behind a connection.','UFO Files Relationships view with connected people, places, and subjects from the archive'],document:['Documents','Where can I read the underlying record?','Browse cataloged files, identify their collections, and open the source text for closer reading.','UFO Files Document Finder with source titles, collections, and links'],map:['Map','Which places are mentioned in the records?','Explore geographic references from the archive. A place mentioned in a document is not necessarily a sighting location.','UFO Files Map view showing geographic references from the corpus'],clock:['Clock','What times do the accounts describe?','Compare time-of-day references extracted from documents. Field Station recording times are kept distinct from documentary mentions.','UFO Files Clock view showing time-of-day references from the corpus'],signals:['Signals','Which radio frequencies recur in the material?','Compare frequency mentions and inspect their context. Documentary mentions are distinct from receiver measurements.','UFO Files Signals view showing frequency mentions across the radio spectrum']};
const image=document.getElementById('files-preview-image'),dialog=document.getElementById('files-image-dialog'),buttons=[...document.querySelectorAll('[data-files-view]')];let request=0;
buttons.forEach(button=>button.addEventListener('click',async()=>{const token=++request,key=button.dataset.filesView,entry=views[key],next=new Image();next.src=`assets/ufo-files/${key}.webp`;try{await next.decode()}catch{return}if(token!==request)return;image.src=next.src;image.alt=entry[3];document.getElementById('files-view-question').textContent=entry[1];document.getElementById('files-view-answer').textContent=entry[2];document.getElementById('files-enlarge').setAttribute('aria-label',`Enlarge ${entry[0]} screenshot`);buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)))}));
document.getElementById('files-enlarge').addEventListener('click',()=>{const enlarged=dialog.querySelector('img');enlarged.src=image.src;enlarged.alt=image.alt;dialog.showModal()});dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
})();
